  $j$[{"kind": "kb_sights row", "name": "sight 1824 (id 2030), inserted 21:41 CST 2026-11-25", "before": "no row", "after": "summary 15,675 characters md5 5238081ce20721073811eedf7a1d2004; L1-L2-L3; SUBSTANTIALLY_SUPPORTED; production_safe true; embedded 22:00 CST (Wall 12339); notes counts corrected 21:46 CST (Wall 12333)"}, {"kind": "kb_sights row", "name": "sight 1407 (id 1593), column summary, 22:17 CST 2026-11-25", "before": "closes with the trinitarian benediction:", "after": "closes with the benediction: (one word removed); md5 d5b187068ae772b02ababbff13e4bb62, 1,294; embedding not refreshed"}, {"kind": "kb_sights row", "name": "sight 1345 (id 1528), column summary, 22:17 CST 2026-11-25", "before": "summary without the pointer", "after": "appended: Matthew 12:24-32 is read in Sight 1824 part (9). md5 714cd2ce65a3b8d23c2b6cd40d058903, 1,544; embedding not refreshed"}, {"kind": "kb_sights row", "name": "sight 1825 (id 2031), inserted 2026-11-26 00:16 CST: Born of the Spirit", "before": "no row", "after": "summary 7,071 characters md5 f4bd6406566de262b7c1ee1248d3fd80; L1-L2-L3; SUBSTANTIALLY_SUPPORTED; production_safe true; embedding NULL at the write"}, {"kind": "kb_sights row", "name": "sight 1826 (id 2032), inserted 2026-11-26 00:16 CST: The Promised Sons", "before": "no row", "after": "summary 7,531 characters md5 a81f0e991f367ff6243306fc1165a1be; L1-L2-L3; SUBSTANTIALLY_SUPPORTED; production_safe true; embedding NULL at the write"}, {"kind": "kb_sights row", "name": "sight 1827 (id 2033), inserted 2026-11-26 00:17 CST: Christ Means Anointed", "before": "no row", "after": "summary 8,047 characters md5 e787d3d3841f1c0e207f9626e8a54805; L1-L2-L3; SUBSTANTIALLY_SUPPORTED; production_safe true; embedding NULL at the write"}, {"kind": "kb_sights row", "name": "sight 1828 (id 2034), inserted 2026-11-26 00:18 CST: Gennao (G1080), Every Row", "before": "no row", "after": "summary 5,837 characters md5 a4d305e0ac4568b5273534db1a75650e; L1-L2-L3; SUBSTANTIALLY_SUPPORTE